parameters.jsCode:
const body = $input.first().json.body || $input.first().json;

// Strict validation gates
if (!body.lesson_id) throw new Error('Missing parameter: lesson_id');
if (!body.section)   throw new Error('Missing parameter: section'); 

// FIXED: Added 'lesson_plan' and 'answerkey' aliases to match all Lovable naming conventions perfectly
const tableMap = {
  lesson:         'lesson_content',
  lesson_plan:    'lesson_content',
  worksheet:      'worksheets',
  quiz:           'quizzes',
  rubric:         'rubrics',
  answer_key:     'answer_keys',
  answerkey:      'answer_keys'
};

// FIXED: Added matching prompt schema aliases 
const schemas = {
  lesson: `{"title":"","objectives":[],"warmup":{"activity":"","duration":"","description":""},"mainContent":[{"concept":"","explanation":"","example":""}],"activity":{"title":"","duration":"","instructions":""},"recap":{"keyPoints":[],"checkQuestions":[]},"homework":{"assignment":"","dueDate":""}}`,
  worksheet: `{"title":"","sections":[{"type":"fill_blanks","title":"Section A","questions":[]},{"type":"short_answer","title":"Section B","questions":[{"question":"","marks":2}]}]}`,
  quiz: `{"title":"","totalMarks":20,"duration":"20 minutes","sections":{"mcq":[{"question":"","options":["A. ","B. ","C. ","D. "],"correct":"A"}],"trueFalse":[{"statement":"","answer":true}],"shortAnswer":[{"question":"","marks":3}]}}`,
  rubric: `{"title":"","totalPoints":16,"criteria":[{"name":"","weight":25,"excellent":{"points":4,"description":""},"good":{"points":3,"description":""},"satisfactory":{"points":2,"description":""},"needsWork":{"points":1,"description":""}}]}`,
  answer_key: `{"title":"Answer Key","worksheetAnswers":{"fillBlanks":[],"shortAnswers":[]},"quizAnswers":{"mcq":[],"trueFalse":[],"shortAnswers":[]}}`
};

// Map aliases to common structure fallback roots safely
const normalizedSection = body.section.toLowerCase().trim();
const targetTable = tableMap[normalizedSection];
const schemaKey = (normalizedSection === 'lesson_plan') ? 'lesson' : (normalizedSection === 'answerkey' ? 'answer_key' : normalizedSection);

if (!targetTable || !schemas[schemaKey]) {
  throw new Error(`${body.section} Invalid section identifier`);
}

const prompt = `CRITICAL OUTPUT RULE: Return ONLY a raw JSON object. No markdown fences. No code blocks. No explanation text. Start with { and end with }.

You are an elite curriculum designer. Generate a completely fresh, brand-new replacement version for the educational component: ${body.section.toUpperCase()}.
Do not repeat identical questions or copy-paste phrasing from previous generations.

CLASS PARAMETERS:
SUBJECT: ${body.subject || 'Mathematics'}
GRADE: ${body.grade || 'Grade 8'}
TOPIC: ${body.topic || 'Trigonometry'}
LANGUAGE: ${body.language || 'English'}
DIFFICULTY: ${body.difficulty || 'Medium'}

OUTPUT THIS EXACT JSON STRUCTURE SCHEMA:
${schemas[schemaKey]}`;

return [{
  json: {
    lesson_id:  body.lesson_id,
    user_id:    body.user_id,
    section:    normalizedSection,
    table_name: targetTable,
    prompt:     prompt
  }
}];

const geminiResponse = $input.first().json;
const context = $('Build Regenerate Context').first().json;

function robustParse(text) {
  if (!text) throw new Error('Empty text received from AI.');
  let t = text.trim();
  t = t.replace(/^```json\s*/i, '').replace(/\s*```$/i, '');
  t = t.replace(/^```\s*/i, '').replace(/\s*```$/i, '');

  const start = t.indexOf('{');
  const end   = t.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('Invalid JSON structure returned by Gemini.');

  t = t.slice(start, end + 1);
  // Flatten raw literal line breaks inside strings breaking JSON specs
  t = t.replace(/\r?\n|\r/g, ' ').replace(/\t/g, ' ');
  return JSON.parse(t);
}

const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text || '';
const freshContent = robustParse(rawText);

return [{
  json: {
    lesson_id:  context.lesson_id,
    section:    context.section,
    table_name: context.table_name,
    content:    freshContent
  }
}];
